sys_script.script:
// B.3 ITF Requisition Validation
//
// Business rule script for x_snc_sas_positi_0_req_task. Loaded via Now.include().
// Legacy (non-module) script using the platform-injected globals.
//
// Runs `before insert, update` with no condition (per spec): a requisition task
// may not exist at all unless its parent case was approved, so the parent check
// must run on every save.
//
// Enforces: parent case approved; emergency hires routed to a separate process;
// minimum advertising days unless an exemption applies.
// Never calls current.update() — this is a before rule.
(function executeRule(current, previous) {
    var c = new GlideRecord('x_snc_sas_positi_0_case');
    if (!c.get(current.getValue('parent')) || c.getValue('committee_decision') != 'approved') {
        gs.addErrorMessage(gs.getProperty('x_snc_sas_positi_0.msg_requisition_not_approved'));
        current.setAbortAction(true);
        return;
    }

    if (current.submitted_on.changes() && !current.submitted_on.nil()) {
        var reason = current.getValue('posting_exemption_reason');
        if (reason == 'emergency') {
            gs.addErrorMessage(gs.getProperty('x_snc_sas_positi_0.msg_emergency_hire'));
            current.setAbortAction(true);
            return;
        }

        // Fail loud rather than silently skipping the advertising-days control
        // if the minimum is not configured.
        var min = parseInt(gs.getProperty('x_snc_sas_positi_0.min_posting_business_days'), 10);
        var days = parseInt(current.getValue('posting_business_days') || '0', 10);
        if (isNaN(min)) {
            gs.error('ITF: x_snc_sas_positi_0.min_posting_business_days is not set');
            current.setAbortAction(true);
            return;
        }

        if (!reason && days < min) {
            gs.addErrorMessage(gs.getProperty('x_snc_sas_positi_0.msg_posting_days'));
            current.setAbortAction(true);
        }
    }
})(current, previous);
